52	/** Helper functions to determine sizes needed in BLAS/LAPACKE routines */
53	struct mat_sizes {
54	  size_t nr, nc;
55	};
56	
57	static inline struct mat_sizes get_mat_sizes(enum gkyl_mat_trans trans, const struct gkyl_mat *A)
58	{
59	  if (trans == GKYL_NO_TRANS)
60	    return (struct mat_sizes){ .nr = A->nr, .nc = A->nc };
61	  return (struct mat_sizes){ .nr = A->nc, .nc = A->nr };
62	}
63	
64	struct gkyl_mat *gkyl_mat_clone(const struct gkyl_mat *in)
65	{
66	  struct gkyl_mat *m = gkyl_malloc(sizeof(struct gkyl_mat));
67	  m->data = gkyl_malloc(sizeof(double[in->nr * in->nc]));
68	  m->nc = in->nc;
69	  m->nr = in->nr;
70	  size_t tot = sizeof(double[in->nr * in->nc]);
71	  memcpy(m->data, in->data, tot);
72	  return m;
73	}
74	
75	struct gkyl_mat *gkyl_mat_diag(struct gkyl_mat *mat, double val)
76	{
77	  gkyl_mat_clear(mat, 0.0);
78	  for (size_t i = 0; i < GKYL_MIN2(mat->nr, mat->nc); ++i)
79	    gkyl_mat_set(mat, i, i, val);
80	  return mat;
81	}
82	
83	void gkyl_mat_show(const char *name, FILE *fp, const struct gkyl_mat *mat)
84	{
85	  fprintf(fp, "%s : matrix( ", name);
86	
87	  for (int i = 0; i < mat->nr - 1; ++i) {
88	    fprintf(fp, "[");
89	    for (int j = 0; j < mat->nc - 1; ++j) {
90	      fprintf(fp, "%lg, ", gkyl_mat_get(mat, i, j));
91	    }
92	    fprintf(fp, "%lg ", gkyl_mat_get(mat, i, mat->nc - 1));
93	    fprintf(fp, "], ");
94	  }
95	
96	  fprintf(fp, "[");
97	  for (int j = 0; j < mat->nc - 1; ++j) {
98	    fprintf(fp, "%lg, ", gkyl_mat_get(mat, mat->nr - 1, j));
99	  }
100	  fprintf(fp, "%lg ", gkyl_mat_get(mat, mat->nr - 1, mat->nc - 1));
101	  fprintf(fp, "] ");
102	
103	  fprintf(fp, " )\n");
104	}
105	
106	#ifdef GKYL_HAVE_CUDA
107	void cu_mat_mm(double alpha, double beta, enum gkyl_mat_trans transa, const struct gkyl_mat *A,
108	               enum gkyl_mat_trans transb, const struct gkyl_mat *B, struct gkyl_mat *C)
109	{
110	  // device handle
111	  cublasHandle_t cuh;
112	  cublasCreate_v2(&cuh);
113	
114	  // determine matrix sizes
115	  struct mat_sizes sza = get_mat_sizes(transa, A);
116	  struct mat_sizes szb = get_mat_sizes(transb, B);
117	  struct mat_sizes szc = get_mat_sizes(GKYL_NO_TRANS, C);
118	
119	  // intermediate size
120	  size_t k = sza.nc; // same as szb.nr
121	  size_t lda = transa == GKYL_NO_TRANS ? C->nr : k;
122	  size_t ldb = transb == GKYL_NO_TRANS ? k : C->nc;
123	  size_t ldc = C->nr;
124	
125	  assert((sza.nr == szc.nr) && (sza.nc == k) && (szb.nr == k) && (szb.nc == szc.nc));
126	
